青蛙每次能跳1或2步，下面代码计算青蛙跳到第n步台阶有多少种不同跳法。则下列说法，错误的是()。
```cpp
int jump_recur(int n){
    if (n == 1) return 1;
    if (n == 2) return 2;
    return jump_recur(n -1) + jump_recur(n -2);
}
int jump_dp(int n){
    vector<int> dp(n + 1);
    dp[1] = 1;
    dp[2] = 2;
    for (int i = 3; i <= n; ++i) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    return dp[n];
}
```

